input.content:
workspace "Sistema de Agendamento" "Agendamento de compromissos com lembretes por SMS." {

    !identifiers hierarchical

    model {
        agendamento = softwareSystem "Sistema de Agendamento" "Permite criar e consultar agendamentos e envia lembretes por SMS." {
            mobile = container "App Mobile" "Interface mobile para o uso do sistema de agendamento." "Flutter" "Mobile App"
            painel = container "Painel Web" "Interface web para o uso do sistema de agendamento." "Vue" "Web Browser"
            api = container "API" "Expõe as operações de agendamento e dispara os lembretes por SMS." "Python, FastAPI"
            db = container "Banco de Dados" "Armazena os agendamentos." "PostgreSQL 15" "Database"

            mobile -> api "Consulta e grava agendamentos via" "HTTPS"
            painel -> api "Consulta e grava agendamentos via" "HTTPS"
            api -> db "Lê e grava agendamentos em" "SQL"
        }

        twilio = softwareSystem "Twilio" "Plataforma de comunicação que entrega mensagens SMS." "External"

        agendamento.api -> twilio "Envia lembretes por SMS via" "HTTPS"
    }

    views {
        systemContext agendamento "SystemContext" {
            include *
            autoLayout
        }

        container agendamento "Containers" {
            include *
            autoLayout
        }

        styles {
            element "Element" {
                color #ffffff
            }
            element "Software System" {
                background #1168bd
            }
            element "Container" {
                background #438dd5
            }
            element "External" {
                background #8c8c8c
            }
            element "Database" {
                shape cylinder
            }
            element "Mobile App" {
                shape mobiledeviceportrait
            }
            element "Web Browser" {
                shape webbrowser
            }
        }
    }

    configuration {
        scope softwaresystem
    }

}

